package com.tripmateai.service.impl; import com.tripmateai.entity.*; import com.tripmateai.exception.UnauthorizedException; import com.tripmateai.repository.RefreshTokenRepository; import com.tripmateai.service.RefreshTokenService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.time.*; import java.util.UUID; @Service @RequiredArgsConstructor public class RefreshTokenServiceImpl implements RefreshTokenService {private final RefreshTokenRepository repo; public RefreshToken create(User u){var t=new RefreshToken();t.setUser(u);t.setToken(UUID.randomUUID().toString());t.setExpiresAt(LocalDateTime.now().plusDays(30));return repo.save(t);} public RefreshToken validate(String token){var t=repo.findByToken(token).orElseThrow(()->new UnauthorizedException("Invalid refresh token"));if(t.isRevoked()||t.getExpiresAt().isBefore(LocalDateTime.now()))throw new UnauthorizedException("Expired refresh token");return t;} public void revoke(String token){repo.findByToken(token).ifPresent(t->{t.setRevoked(true);repo.save(t);});}}
